-- Miora knowledge pack v2: structured original study notes with authoritative references.
-- Run in Supabase SQL Editor after 202611050001_knowledge_resources.sql.
-- Notes summarize public guidance; they are not copied source chapters.
insert into public.knowledge_resources
(title, source_name, source_url, resource_type, topic_tags, content, reviewed_at, review_status)
values
('Psychological first aid: look, listen, link', 'World Health Organization',
 'https://www.who.int/publications/i/item/9789241548205', 'Field guide',
 array['psychological first aid','listening','distress','crisis','practical support','human connection'],
 'STUDY NOTES: Psychological first aid is humane, supportive and practical help for people affected by serious distressing events. Its core actions are LOOK (notice safety, urgent basic needs and serious distress), LISTEN (approach respectfully, ask about needs, listen without pressuring people to tell their story, help them feel calm and safe), and LINK (connect with practical support, loved ones and services). Do not force disclosure, make promises you cannot keep, or assume everyone wants the same help. This is not psychotherapy or a substitute for emergency care. Use the principles as a respectful support framework, not as a claim that Miora is a trained PFA provider.',
 now(), 'approved'),
('Doing What Matters in Times of Stress', 'World Health Organization',
 'https://www.who.int/publications/i/item/9789240003927', 'Evidence-informed self-help guide',
 array['stress','grounding','rumination','acceptance','values','self-compassion','distress'],
 'STUDY NOTES: WHO describes practical skills for coping with adversity: grounding attention in the present; noticing and naming thoughts and feelings; unhooking from repetitive thoughts; making room for difficult feelings; acting in line with personal values; and treating oneself with kindness. Offer one skill only when wanted or clearly useful. Explain its purpose, invite rather than prescribe, and adapt if attention to bodily sensations increases distress. These skills can support coping but do not remove the causes of hardship or replace needed care.',
 now(), 'approved'),
('Depression in adults: recognition and support principles', 'National Institute for Health and Care Excellence',
 'https://www.nice.org.uk/guidance/ng222', 'Clinical guideline',
 array['depression','low mood','withdrawal','behavioural activation','self-help','professional support'],
 'STUDY NOTES: Low mood and depression can affect emotion, thinking, sleep, energy, appetite, concentration, motivation and daily functioning; presentations vary. Do not diagnose from chat or assume sadness alone means depression. Ask about duration, impact and context when relevant, without conducting an unsolicited assessment. NICE describes several evidence-based treatment options, including guided self-help and structured psychological therapies, selected according to severity, needs and preferences. Miora can provide general information and encourage appropriate professional assessment when symptoms persist, worsen or impair daily life; it cannot diagnose or deliver a full clinical treatment.',
 now(), 'approved'),
('Anxiety disorders: understanding fear and avoidance', 'National Institute of Mental Health',
 'https://www.nimh.nih.gov/health/topics/anxiety-disorders', 'Public health information',
 array['anxiety','fear','worry','panic','avoidance','uncertainty','professional support'],
 'STUDY NOTES: Anxiety disorders involve more than occasional worry; fear or anxiety can persist, become difficult to control and interfere with daily life. Symptoms and conditions differ. Avoid diagnosing based on a single symptom. A useful explanatory model is that threat anticipation can lead to avoidance, which may bring short-term relief while keeping feared situations difficult over time. This is a possible pattern, not a universal explanation. Ask what the person experiences and how it affects them before offering strategies. Evidence-based treatments exist, and a health professional can help assess persistent or impairing symptoms.',
 now(), 'approved'),
('Trauma-informed approach: safety, trust, choice and collaboration', 'Substance Abuse and Mental Health Services Administration',
 'https://www.samhsa.gov/mental-health/trauma-violence/trauma-informed-approaches', 'Framework',
 array['trauma-informed','safety','choice','trust','collaboration','empowerment','boundaries'],
 'STUDY NOTES: A trauma-informed approach recognizes that trauma may affect people and seeks to avoid re-traumatization. Common principles include safety; trustworthiness and transparency; peer support; collaboration and mutuality; empowerment, voice and choice; and attention to cultural, historical and gender factors. In conversation, do not demand details, push exposure, label a person as traumatized, or assume a trauma history. Offer choice, explain why a question is being asked, respect a refusal, and prioritize control and dignity. These principles guide interaction; they are not a diagnostic tool.',
 now(), 'approved'),
('Behavioural activation: activity, avoidance and mood', 'National Institute for Health and Care Excellence',
 'https://www.nice.org.uk/guidance/ng222/chapter/recommendations', 'Clinical guideline study notes',
 array['behavioural activation','depression','avoidance','activity','mood','routine','withdrawal'],
 'STUDY NOTES: Behavioural activation explores links between activity, avoidance and mood, then supports planned engagement in meaningful or potentially rewarding activity. A conversational adaptation may help when the person explicitly wants practical help: collaboratively choose one small, realistic activity, define when and where, and review what they noticed without judging success or failure. Do not prescribe activity in response to every painful disclosure. Formal behavioural activation is a structured psychological intervention and should be delivered by appropriately trained practitioners; Miora must not claim to provide the full treatment.',
 now(), 'approved'),
('Motivational interviewing: partnership and autonomy', 'SAMHSA',
 'https://www.samhsa.gov/resource/dbhis/tip-35-enhancing-motivation-change-substance-use-disorder-treatment', 'Practice improvement protocol',
 array['motivational interviewing','ambivalence','change','autonomy','reflective listening','values'],
 'STUDY NOTES: Motivational interviewing is a collaborative, goal-oriented communication approach that pays particular attention to the language of change. Its spirit includes partnership, acceptance, compassion and evocation. Core skills include open questions, affirmations, reflections and summaries, but these are not a formula to apply mechanically. Explore the person''s own reasons, values and uncertainty; avoid arguing, persuading, shaming or taking over decisions. Miora can borrow respectful communication principles but must not claim to conduct formal MI or use it to manipulate a person toward a predetermined choice.',
 now(), 'approved'),
('Grief: supporting people after a death', 'National Health Service',
 'https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/feelings-and-symptoms/grief-bereavement-loss/', 'Public health information',
 array['grief','bereavement','loss','sadness','anger','guilt','support'],
 'STUDY NOTES: Grief is an individual response to loss and can involve sadness, longing, anger, guilt, numbness, changes in sleep and concentration, and waves of emotion. There is no single timetable or required sequence. Avoid stages-of-grief scripts, silver linings and statements that impose meaning. Acknowledge the specific person or thing lost and the way the absence appears in daily life. Offer practical support or professional help when wanted or when distress is prolonged, severe, or creates safety concerns.',
 now(), 'approved'),
('Self-compassion: responding to personal difficulty without self-attack', 'Center for Mindful Self-Compassion',
 'https://centerformsc.org/learn-mindful-self-compassion/', 'Educational resource',
 array['self-compassion','shame','self-criticism','self-worth','kindness','common humanity'],
 'STUDY NOTES: Self-compassion is commonly described through self-kindness rather than harsh self-judgment, recognition that difficulty is part of human life rather than proof of personal defect, and mindful awareness that neither suppresses nor exaggerates pain. It is not self-pity, excusing harmful behaviour or forced positive thinking. When shame is present, first understand what happened and what the person is judging themselves for; do not rush to a generic affirmation. If invited, help them consider what they would say to someone they care about in the same situation.',
 now(), 'approved'),
('Healthy relationships: communication, respect and boundaries', 'Government of Canada',
 'https://www.canada.ca/en/public-health/services/health-promotion/stop-family-violence.html', 'Public health resource',
 array['relationships','communication','respect','boundaries','family violence','safety','coercion'],
 'STUDY NOTES: Healthy relationships involve respect, safety, communication, trust, equality and the ability to express needs and boundaries. Relationship conflict is not automatically abuse, and a single description is not enough to label another person. Look for patterns such as intimidation, coercion, isolation, threats, monitoring or fear of retaliation when considering safety. A boundary describes what the person chooses for their own participation and protection; it is not a tool to force another person to confess or change. If credible danger is disclosed, prioritize private safety planning and specialist local support rather than confrontation or couples communication exercises.',
 now(), 'approved'),
('988 Canada: suicide crisis support', 'Government of Canada',
 'https://988.ca/', 'Crisis resource',
 array['suicide','crisis','self-harm','immediate support','Canada','safety'],
 'RESOURCE NOTES: In Canada, 988 provides suicide crisis support by call or text, 24 hours a day, every day. If someone may be in immediate danger or needs urgent medical help, contact 911 or go to an emergency department. Ask directly and calmly about immediate safety when suicide risk is suggested; do not rely on vague reassurance, debate, or a long self-help exercise. Miora is not an emergency service and must encourage connection with a real person who can help. Confirm location when providing country-specific resources.',
 now(), 'approved'),
('Sleep health: basic sleep habits and when to seek help', 'Public Health Agency of Canada',
 'https://www.canada.ca/en/public-health/services/publications/healthy-living.html', 'Public health information',
 array['sleep','insomnia','fatigue','stress','routine','health'],
 'STUDY NOTES: Sleep is affected by health, stress, routines, environment, substances and many other factors. General sleep-supportive habits may include a consistent wake time, a dark and quiet sleep environment, limiting late caffeine, and a wind-down routine. These are general options, not universal prescriptions; avoid blaming someone for poor sleep or implying sleep hygiene alone treats chronic insomnia. Persistent sleep difficulty, severe daytime impairment, breathing problems during sleep or other concerning symptoms warrant discussion with a healthcare professional. Use a more specific source when giving detailed clinical guidance.',
 now(), 'approved'),
('Cognitive behavioural therapy: thoughts, feelings and behaviour', 'National Health Service',
 'https://www.nhs.uk/mental-health/talking-therapies-medicine-treatments/talking-therapies-and-counselling/cognitive-behavioural-therapy-cbt/', 'Public health information',
 array['CBT','thoughts','feelings','behaviour','anxiety','depression','thinking patterns'],
 'STUDY NOTES: CBT explores connections among thoughts, feelings, physical sensations and behaviour, and how patterns can reinforce distress. It does not mean that problems are imaginary or that a person can think their way out of harmful circumstances. A careful conversational use is to ask whether the person wants to examine one thought, distinguish what is known from what is feared, and consider alternative explanations without invalidating real events. Do not dispute a person''s account of abuse, discrimination or betrayal by calling it a cognitive distortion. Miora may explain basic ideas but must not claim to provide formal CBT.',
 now(), 'approved')
on conflict do nothing;
